import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import { MemoryRouter, Route, Routes, useLocation } from 'react-router-dom'

// Generated by /ship test coverage audit (2026-11-15).
// Value: protects=/developers/keys and /developers/usage wait for the session,
//   then send a signed-out reader to /auth with ?next= back to the same page;
//   fails_when=the authLoading guard is dropped (a signed-in reader opening the
//   URL directly is bounced to /auth) or the redirect loses ?next=;
//   why_new=no test renders ApiKeyManager or UsageDashboard, and neither page is
//   in GATED_PATHS, so AccessGate.test.jsx does not cover them;
//   seam=none;
//   no_claim=key and usage loading from Supabase (the client is a stub here)

const auth = vi.hoisted(() => ({ user: null, loading: true }))
vi.mock('../../src/context/AuthContext', () => ({ useAuth: () => auth }))

const sb = vi.hoisted(() => ({ from: null }))
vi.mock('../../src/lib/supabase', () => ({ supabase: { from: (...a) => sb.from(...a) } }))

import ApiKeyManager from '../../src/components/ApiKeyManager'
import UsageDashboard from '../../src/components/UsageDashboard'

// Every query answers "no rows": enough for a page to start loading its data.
function emptyQuery() {
  const q = {}
  for (const m of ['select', 'insert', 'eq', 'in', 'gte', 'order', 'limit']) q[m] = () => q
  q.single = () => Promise.resolve({ data: null, error: { message: 'no rows' } })
  q.then = (resolve) => resolve({ data: null, error: null })
  return q
}

function Where() {
  const loc = useLocation()
  return <output data-testid="where">{`${loc.pathname}${loc.search}`}</output>
}

const PAGES = [
  ['/developers/keys', ApiKeyManager],
  ['/developers/usage', UsageDashboard],
]

function tree(path, Page) {
  return (
    <MemoryRouter initialEntries={[path]}>
      <Routes>
        <Route path={path} element={<Page />} />
        <Route path="*" element={<Where />} />
      </Routes>
    </MemoryRouter>
  )
}

beforeEach(() => {
  auth.user = null
  auth.loading = true
  sb.from = vi.fn(() => emptyQuery())
})

afterEach(cleanup)

describe('developer pages and the session', () => {
  it.each(PAGES)('%s stays put while the session loads, then sends a signed-out reader to sign in and back', (path, Page) => {
    const { rerender } = render(tree(path, Page))
    expect(screen.queryByTestId('where')).toBeNull()
    expect(sb.from).not.toHaveBeenCalled()

    auth.loading = false
    rerender(tree(path, Page))
    expect(screen.getByTestId('where').textContent).toBe(`/auth?next=${encodeURIComponent(path)}`)
    expect(sb.from).not.toHaveBeenCalled()
  })

  it.each(PAGES)('%s keeps a signed-in reader on the page once the session arrives', async (path, Page) => {
    const { rerender } = render(tree(path, Page))
    auth.loading = false
    auth.user = { id: 'u1', email: 'a@b.co' }
    rerender(tree(path, Page))
    await waitFor(() => expect(sb.from).toHaveBeenCalledWith('organizations'))
    expect(screen.queryByTestId('where')).toBeNull()
  })
})

// Extended by /ship test coverage audit (2026-11-17).
// Value: protects=revoking an API key takes two clicks in the key's own row:
//   "Revoke" only opens the confirmation, "Keep key" backs out without a write,
//   and only "Revoke key" sets active=false on that key's id;
//   fails_when=the first click writes straight to api_keys (the confirmation
//   step is lost now that window.confirm is gone), "Keep key" still revokes, or
//   the update targets another key;
//   why_new=nothing rendered the key list before; the tests above stop at the
//   session guard;
//   seam=none;
//   no_claim=Supabase accepting the update or row-level security (the client is
//   a recording stub)
describe('revoking an API key', () => {
  const KEYS = [
    { id: 'k1', name: 'production', key_prefix: 'bw_live_aaaa', active: true, created_at: '2026-11-01T00:00:00Z', monthly_count: 3 },
    { id: 'k2', name: 'staging', key_prefix: 'bw_live_bbbb', active: true, created_at: '2026-11-02T00:00:00Z', monthly_count: 0 },
  ]
  let updates

  // organizations answers one org; api_keys lists KEYS and records every update.
  function keysClient(table) {
    const q = { patch: null }
    for (const m of ['select', 'insert', 'in', 'gte', 'order', 'limit']) q[m] = () => q
    q.update = (patch) => { q.patch = patch; return q }
    q.eq = (col, val) => { if (q.patch) updates.push({ table, patch: q.patch, col, val }); return q }
    q.single = () => Promise.resolve({ data: { id: 'org1', subscription_status: 'active', plan: 'free' }, error: null })
    q.then = (resolve) => resolve({ data: table === 'api_keys' && !q.patch ? KEYS : null, error: null })
    return q
  }

  async function renderKeys() {
    auth.loading = false
    auth.user = { id: 'u1', email: 'a@b.co' }
    updates = []
    sb.from = vi.fn(keysClient)
    render(tree('/developers/keys', ApiKeyManager))
    await screen.findByText('production')
    return screen.getByText('production').closest('.api-key-row')
  }

  it('asks in the row first, and "Keep key" backs out without writing', async () => {
    const row = await renderKeys()
    fireEvent.click(within(row).getByRole('button', { name: 'Revoke' }))

    const confirm = screen.getByRole('group', { name: 'Revoke production' })
    expect(row.contains(confirm)).toBe(true)
    expect(confirm.textContent).toMatch(/integrations using it will immediately stop working/)
    expect(updates).toEqual([])
    // The other key keeps its plain button: one confirmation at a time.
    expect(screen.getAllByRole('button', { name: 'Revoke' })).toHaveLength(1)

    fireEvent.click(within(confirm).getByRole('button', { name: 'Keep key' }))
    expect(screen.queryByRole('group', { name: 'Revoke production' })).toBeNull()
    expect(within(row).getByRole('button', { name: 'Revoke' })).toBeTruthy()
    expect(updates).toEqual([])
  })

  it('"Revoke key" deactivates that key only and closes the confirmation', async () => {
    const row = await renderKeys()
    fireEvent.click(within(row).getByRole('button', { name: 'Revoke' }))
    fireEvent.click(screen.getByRole('button', { name: 'Revoke key' }))

    await waitFor(() => expect(updates).toEqual([{ table: 'api_keys', patch: { active: false }, col: 'id', val: 'k1' }]))
    expect(screen.queryByRole('group', { name: 'Revoke production' })).toBeNull()
  })
})
